CREATE TABLE Teachers (
  TeacherID VARCHAR(5) PRIMARY KEY,
  TeacherName VARCHAR(40)
);
CREATE TABLE Courses (
  CourseID VARCHAR(5) PRIMARY KEY,
  CourseName VARCHAR(40),
  TeacherID VARCHAR(5),
  FOREIGN KEY (TeacherID) REFERENCES Teachers(TeacherID)
);

CREATE TABLE Results (
  StudentID VARCHAR(5) REFERENCES Students(StudentID),
  SubjectCode VARCHAR(6) REFERENCES Subjects(SubjectCode),
  Mark INTEGER,
  PRIMARY KEY (StudentID, SubjectCode)
);

